class Center {
  + Name : string
  + Address : string
}

class Room {
  + RoomNumber : int
  + MaxCapacity : int
}

class Person {
  + FirstName : string
  + FamilyName : string
  + BirthDate : date
}

class Trainer {
  + Diploma : string
}

class Member {
}

class Prospect {
}

class Intern {
}

class Session {
  + Date : date
  + StartHour : time
}

class IndividualSession {
}

class GroupSession {
  + Type : string
}

Center "1" *-- "1..*" Room
Room "1" -- "0..*" Session
Person "1" -- "0..*" Trainer : is
Person "1" -- "0..*" Member : is
Person "1" -- "0..*" Prospect : is
Person "1" -- "0..*" Intern : is

Trainer "1" -- "0..*" GroupSession : supervises
Person "1" -- "0..*" Session : participates

Session "1" -- "0..1" IndividualSession : is
Session "1" -- "0..1" GroupSession : is

IndividualSession --|> Session
GroupSession --|> Session

@enduml

